// Aquí formateas el mensaje de bienvenida y código OTP
const phone = $input.item.json.body.phone;
const code = $input.item.json.body.code;
const tenant = $input.item.json.body.tenantName || 'ASYS Barber';

const mensaje = `💈 *${tenant}* (Vía ASYS Control)\n\nTu código de verificación de WhatsApp es:\n\n🔑 *${code}*\n\nIngresa este código en la pantalla de registro para validar tu cuenta. Expira en 10 minutos.`;

return {
  phone,
  mensaje
};

// Aquí formateas el mensaje de cita agendada
const data = $input.item.json.body;

const mensaje = `✂️ *¡Cita Confirmada!* - ${data.tenantName}

Hola *${data.clientName}*, tu turno ha quedado reservado con éxito.

📅 *Fecha:* ${data.date}
⏰ *Hora:* ${data.time}
💈 *Barbero:* ${data.barberName}
💇‍♂️ *Servicio:* ${data.serviceName}
💰 *Total:* $${Number(data.price).toLocaleString('es-CO')} COP

📍 _Mensaje enviado automáticamente desde el centro digital de barberías ASYS Barber._`;

return {
  phone: data.clientPhone,
  mensaje
};
